#include <stdio.h>
#include <stddef.h>

struct A { char a; int b; char c; };                 /* 有明显的内部填充 */
struct B { int b; char a; char c; };                 /* 按大小降序排列 */
struct C { char a; char b; int c; };                 /* 小的放前面 */
struct P { char pad[64]; int counter; };             /* 缓存行填充：独占一行 */

int main(void) {
    printf("=== struct layout, padding and cache lines (line = 64 B) ===\n\n");

    printf("struct A { char a; int b; char c; }\n");
    printf("   sizeof=%2d  align=%d  offsetof: a=%d b=%d c=%d\n",
           (int)sizeof(struct A), (int)_Alignof(struct A),
           (int)offsetof(struct A, a), (int)offsetof(struct A, b), (int)offsetof(struct A, c));
    printf("   -> 4 bytes of padding: b must sit on a 4-byte boundary\n");

    printf("\nstruct B { int b; char a; char c; }\n");
    printf("   sizeof=%2d  align=%d  offsetof: b=%d a=%d c=%d\n",
           (int)sizeof(struct B), (int)_Alignof(struct B),
           (int)offsetof(struct B, b), (int)offsetof(struct B, a), (int)offsetof(struct B, c));
    printf("   -> 2 bytes of tail padding only; same fields, 12 -> 8 bytes\n");

    printf("\nstruct C { char a; char b; int c; }\n");
    printf("   sizeof=%2d  align=%d  offsetof: a=%d b=%d c=%d\n",
           (int)sizeof(struct C), (int)_Alignof(struct C),
           (int)offsetof(struct C, a), (int)offsetof(struct C, b), (int)offsetof(struct C, c));

    printf("\nsizeof(A) - sizeof(B) = %d bytes saved just by reordering fields\n",
           (int)(sizeof(struct A) - sizeof(struct B)));
    printf("rule: declare fields from LARGEST to SMALLEST to minimise padding\n");

    printf("\n=== struct P: one cache line per object (false-sharing guard) ===\n");
    printf("   sizeof(struct P) = %d bytes = exactly one 64 B line\n", (int)sizeof(struct P));
    printf("   two counters inside struct P occupy DIFFERENT lines -> no false sharing\n");
    printf("   two plain ints side by side would share one line -> every write invalidates the peer\n");

    printf("\n=== why this matters ===\n");
    printf("   an array of 1e6 struct A objects costs %d MB; as struct B it costs %d MB\n",
           (int)(sizeof(struct A) * 1000000 / 1000000), (int)(sizeof(struct B) * 1000000 / 1000000));
    printf("   fewer bytes touched = fewer cache lines = higher hit rate\n");
    return 0;
}
